-- ViceHub X — Article premium : GTA 6 « An Extended Look » (gameplay du 27 aout 2026).
-- Faits verifies (Netflix Tudum, Variety, GamesRadar, Kotaku, IGN). Idempotent. A lancer dans phpMyAdmin.
ALTER TABLE articles ADD COLUMN IF NOT EXISTS meta_title VARCHAR(90) DEFAULT NULL;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS meta_description VARCHAR(200) DEFAULT NULL;

INSERT INTO articles (category_id, lang, title, slug, excerpt, meta_title, meta_description, body, image, status, published_at)
SELECT (SELECT id FROM categories WHERE slug='news' LIMIT 1), 'fr',
  'GTA 6 Extended Look : tout ce que le gameplay du 27 août a montré',
  'gta-6-extended-look-tout-ce-qui-a-ete-montre',
  'GTA 6 « An Extended Look » : 26 min de gameplay PS5 (Jason & Lucia, fusillades, conduite, braquages). On décrypte tout ce qui a été montré le 27 août.',
  'GTA 6 Extended Look : tout le gameplay du 27 août (2026)',
  'GTA 6 « An Extended Look » : 26 minutes de gameplay capté sur PS5, Jason & Lucia à Vice City. Fusillades, conduite, braquages : on décrypte tout.',
  '<p><strong>Rockstar a enfin montré du gameplay de GTA 6.</strong> Diffusée le <strong>27 août 2026</strong> d''abord sur Netflix puis sur YouTube, la présentation « Grand Theft Auto VI: An Extended Look » offre environ <strong>26 minutes</strong> d''images <strong>100% in-game capturées sur PlayStation 5</strong>. Voici, à notre manière, tout ce qui a été montré.</p><h2>L''essentiel en 5 points</h2><ul><li>~26 minutes de gameplay réel, capté sur PS5, diffusé sur Netflix le 27 août (puis YouTube ~6 h après).</li><li>Jason et Lucia en action à travers Vice City et l''État de Leonida : missions, braquages, fusillades, courses-poursuites.</li><li>Ouverture sur Jason et Lucia entrant dans un immeuble pour récupérer un colis pour un certain « Boobie ».</li><li>Bascule fluide entre gameplay et cinématiques, changement de personnage, IA des PNJ et vie quotidienne.</li><li>La date de sortie reste le <strong>19 novembre 2026</strong> (PS5 et Xbox Series X|S).</li></ul><h2>Ce que la présentation a montré</h2><p>La vidéo enchaîne <strong>missions, braquages, vol de voitures, courses-poursuites avec la police, changement de personnage, interactions avec les PNJ et activités annexes</strong>. Elle s''ouvre sur Jason et Lucia entrant dans un immeuble pour aller chercher un paquet destiné à un personnage nommé <strong>Boobie</strong>, Jason étant jouable dans cette séquence — le tout passant du gameplay à la cinématique sans coupure.</p><h2>Le gunplay : un cover-shooter assumé</h2><blockquote>Confirmé : on voit une fusillade dans un gratte-ciel, Jason se mettant à couvert derrière les murs avant d''ouvrir le feu.</blockquote><p>Le tir paraît nettement plus travaillé que dans GTA 5, avec un système de couverture qui rappelle les shooters dédiés.</p><h2>La conduite : plus nerveuse que GTA 5</h2><p>Une course-poursuite dans Vice City montre qu''<strong>abattre les pneus</strong> des voitures de police est l''un des moyens les plus efficaces de les semer. La conduite paraît plus dynamique que dans GTA 5 : virages plus serrés, freinages brusques, et la possibilité de s''essayer tout de suite à des <strong>courses en voiture ou en dirt-bike</strong>.</p><h2>GTA 6 vs GTA 5 : ce qui saute aux yeux</h2><table><thead><tr><th>Aspect</th><th>GTA 5 (2013)</th><th>GTA 6 — Extended Look</th></tr></thead><tbody><tr><td>Fusillades</td><td>Visée assistée simple</td><td>Cover-shooter travaillé, prise de couverture</td></tr><tr><td>Conduite</td><td>Souple, arcade</td><td>Plus nerveuse, virages serrés, freinages</td></tr><tr><td>Transitions</td><td>Chargements/cinématiques marquées</td><td>Gameplay vers cinématique sans coupure</td></tr><tr><td>Monde</td><td>Los Santos</td><td>Vice City + État de Leonida</td></tr><tr><td>Personnages</td><td>3 protagonistes</td><td>Duo Jason &amp; Lucia, changement de perso</td></tr></tbody></table><h2>Chronologie de GTA 6</h2><ol><li><strong>Déc. 2023</strong> — 1er trailer.</li><li><strong>2025</strong> — 2e trailer.</li><li><strong>27 août 2026</strong> — « An Extended Look » (26 min de gameplay).</li><li><strong>19 nov. 2026</strong> — sortie sur PS5 et Xbox Series X|S.</li></ol><h2>Au-delà de la vidéo publique</h2><blockquote>Rumeur / non confirmé par Rockstar : selon IGN, la presse a pu voir ~30 minutes supplémentaires à Rockstar North, donnant lieu à des dizaines de détails additionnels.</blockquote><p>Ces informations viennent de la presse spécialisée et non d''un communiqué officiel : on les traite comme des compléments à confirmer.</p><h2>Sources &amp; officiel</h2><ul><li>Rockstar Newswire (annonces officielles).</li><li>Netflix Tudum — page « Grand Theft Auto VI: An Extended Look ».</li><li>Chaîne YouTube officielle de Rockstar Games.</li></ul><h2>FAQ</h2><h3>Combien de temps dure la présentation ?</h3><p>Environ 26 minutes, capturées en jeu sur PlayStation 5.</p><h3>Où la revoir gratuitement ?</h3><p>Sur la chaîne YouTube de Rockstar et le site officiel GTA VI (quelques heures après l''avant-première Netflix).</p><h3>La date de sortie a-t-elle changé ?</h3><p>Non : GTA 6 sort toujours le 19 novembre 2026 sur PS5 et Xbox Series X|S.</p>',
  '/public/assets/img/scenes/downtown.png', 'published', '2026-08-28 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug='gta-6-extended-look-tout-ce-qui-a-ete-montre');

INSERT INTO articles (category_id, lang, title, slug, excerpt, meta_title, meta_description, body, image, source_id, status, published_at)
SELECT (SELECT id FROM categories WHERE slug='news' LIMIT 1), 'en',
  'GTA 6 Extended Look: Everything the Aug 27 Gameplay Showed',
  'gta-6-extended-look-everything-shown-ps5',
  'GTA 6 An Extended Look: 26 min of PS5 gameplay (Jason & Lucia, gunfights, driving, robberies). Everything shown on Aug 27, broken down.',
  'GTA 6 Extended Look: All the Aug 27 Gameplay (2026)',
  'GTA 6 An Extended Look: 26 minutes of PS5 gameplay, Jason & Lucia in Vice City. Gunfights, driving, robberies — the full breakdown.',
  '<p><strong>Rockstar finally showed GTA 6 gameplay.</strong> Released on <strong>August 27, 2026</strong> first on Netflix then YouTube, Grand Theft Auto VI: An Extended Look delivers around <strong>26 minutes</strong> of footage <strong>captured entirely in-game on PlayStation 5</strong>. Here is everything it showed, our way.</p><h2>Key takeaways</h2><ul><li>~26 minutes of real gameplay, captured on PS5, aired on Netflix Aug 27 (then YouTube ~6h later).</li><li>Jason and Lucia in action across Vice City and the state of Leonida: missions, robberies, gunfights, police chases.</li><li>Opens with Jason and Lucia entering an apartment building to collect a package for a character named Boobie.</li><li>Seamless switch between gameplay and cutscenes, character switching, NPC AI and everyday life.</li><li>The release date stays <strong>November 19, 2026</strong> (PS5 and Xbox Series X|S).</li></ul><h2>What the showcase revealed</h2><p>The footage strings together <strong>missions, robberies, car theft, police chases, character switching, NPC interactions and side activities</strong>. It opens on Jason and Lucia entering a building to grab a package for a character named <strong>Boobie</strong>, with Jason playable in that sequence — moving from gameplay to cutscene without a cut.</p><h2>Gunplay: a real cover-shooter</h2><blockquote>Confirmed: a firefight in a skyscraper shows Jason taking cover behind walls before opening fire.</blockquote><p>The shooting looks significantly refined compared to GTA 5, with a cover system reminiscent of dedicated shooters.</p><h2>Driving: punchier than GTA 5</h2><p>A car chase through Vice City makes it clear that <strong>shooting the tyres</strong> of pursuing police cars is one of the best ways to lose them. Driving feels more dynamic than GTA 5 — tighter bends, sudden braking — and you can jump straight into <strong>car or dirt-bike races</strong>.</p><h2>GTA 6 vs GTA 5: what stands out</h2><table><thead><tr><th>Aspect</th><th>GTA 5 (2013)</th><th>GTA 6 — Extended Look</th></tr></thead><tbody><tr><td>Gunfights</td><td>Simple auto-aim</td><td>Refined cover-shooter</td></tr><tr><td>Driving</td><td>Loose, arcade</td><td>Punchier, tighter bends, braking</td></tr><tr><td>Transitions</td><td>Noticeable loads/cutscenes</td><td>Seamless gameplay to cutscene</td></tr><tr><td>World</td><td>Los Santos</td><td>Vice City + state of Leonida</td></tr><tr><td>Characters</td><td>3 protagonists</td><td>Jason &amp; Lucia duo, character switch</td></tr></tbody></table><h2>GTA 6 timeline</h2><ol><li><strong>Dec 2023</strong> — first trailer.</li><li><strong>2025</strong> — second trailer.</li><li><strong>Aug 27, 2026</strong> — An Extended Look (26 min of gameplay).</li><li><strong>Nov 19, 2026</strong> — release on PS5 and Xbox Series X|S.</li></ol><h2>Beyond the public video</h2><blockquote>Rumor / unconfirmed by Rockstar: according to IGN, press saw ~30 extra minutes at Rockstar North, yielding dozens of additional gameplay details.</blockquote><p>That comes from specialist press, not an official statement — treat it as to-be-confirmed.</p><h2>Sources &amp; official</h2><ul><li>Rockstar Newswire (official announcements).</li><li>Netflix Tudum — Grand Theft Auto VI: An Extended Look page.</li><li>Rockstar Games official YouTube channel.</li></ul><h2>FAQ</h2><h3>How long is the showcase?</h3><p>About 26 minutes, captured in-game on PlayStation 5.</p><h3>Where to watch it free?</h3><p>On Rockstar''s YouTube channel and the official GTA VI site (a few hours after the Netflix premiere).</p><h3>Did the release date change?</h3><p>No: GTA 6 still launches November 19, 2026 on PS5 and Xbox Series X|S.</p>',
  '/public/assets/img/scenes/downtown.png',
  (SELECT id FROM (SELECT id FROM articles WHERE slug='gta-6-extended-look-tout-ce-qui-a-ete-montre' LIMIT 1) x), 'published', '2026-08-28 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM articles WHERE slug='gta-6-extended-look-everything-shown-ps5');

